import sys
import random
from PyQt5.QtWidgets import (QApplication, QWidget, QLabel, QMenu, QAction,
                             QDesktopWidget)
from PyQt5.QtGui import QPixmap
from PyQt5.QtCore import Qt, QTimer, QPoint
import base64

class DesktopPet(QWidget):
    def __init__(self):
        super().__init__()
        # 窗口设置：无边框、置顶、透明背景
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.SubWindow)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setAutoFillBackground(False)
        
        # 从base64加载宠物图片
        pet_b64 = ""
        pet_data = base64.b64decode(pet_b64)
        self.pet_image = QPixmap()
        self.pet_image.loadFromData(pet_data)
        # 缩放图片到合适大小：宽度200像素，高度按比例
        self.pet_width = 200
        self.pet_height = int(self.pet_image.height() * (self.pet_width / self.pet_image.width()))
        self.pet_image = self.pet_image.scaled(self.pet_width, self.pet_height, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        
        # 创建标签显示图片
        self.pet_label = QLabel(self)
        self.pet_label.setPixmap(self.pet_image)
        self.pet_label.resize(self.pet_width, self.pet_height)
        
        # 设置窗口大小和图片一致
        self.resize(self.pet_width, self.pet_height)
        
        # 初始化宠物位置：屏幕底部居中
        screen = QDesktopWidget().screenGeometry()
        self.move((screen.width() - self.pet_width) // 2, screen.height() - self.pet_height - 50)
        
        # 移动参数
        self.speed_x = random.choice([-1, 1])  # 初始水平方向随机
        self.speed_y = 0
        self.move_timer = QTimer(self)
        self.move_timer.timeout.connect(self.update_position)
        self.move_timer.start(50)  # 每50毫秒移动一次，速度不会太快
        
        # 闲置动画：偶尔上下浮动
        self.float_timer = QTimer(self)
        self.float_timer.timeout.connect(self.float_animation)
        self.float_timer.start(3000)  # 每3秒触发一次浮动
        self.float_offset = 0
        self.float_direction = 1
        
        # 拖拽相关
        self.dragging = False
        self.drag_start_pos = QPoint()
        
    def update_position(self):
        """更新宠物位置，自动移动"""
        if self.dragging:
            return  # 拖拽时不自动移动
        
        screen = QDesktopWidget().screenGeometry()
        current_pos = self.pos()
        
        # 计算新位置
        new_x = current_pos.x() + self.speed_x
        new_y = current_pos.y() + self.speed_y + self.float_offset
        
        # 碰到左右边缘反弹
        if new_x <= 0 or new_x >= screen.width() - self.pet_width:
            self.speed_x = -self.speed_x
            new_x = current_pos.x() + self.speed_x
        
        # 上下边界：限制在任务栏上方，不会跑出屏幕
        if new_y <= 0:
            new_y = 0
        if new_y >= screen.height() - self.pet_height - 50:
            new_y = screen.height() - self.pet_height - 50
        
        self.move(new_x, new_y)
    
    def float_animation(self):
        """闲置时的上下浮动动画"""
        self.float_offset = self.float_direction * 2
        self.float_direction = -self.float_direction
        # 一次浮动后重置偏移
        QTimer.singleShot(300, lambda: setattr(self, 'float_offset', 0))
    
    def mousePressEvent(self, event):
        """鼠标按下事件"""
        if event.button() == Qt.LeftButton:
            self.dragging = True
            self.drag_start_pos = event.globalPos() - self.pos()
            event.accept()
        elif event.button() == Qt.RightButton:
            # 右键弹出菜单
            self.show_context_menu(event.globalPos())
    
    def mouseMoveEvent(self, event):
        """鼠标移动事件：拖拽"""
        if self.dragging and event.buttons() == Qt.LeftButton:
            self.move(event.globalPos() - self.drag_start_pos)
            event.accept()
    
    def mouseReleaseEvent(self, event):
        """鼠标释放事件：结束拖拽"""
        if event.button() == Qt.LeftButton:
            self.dragging = False
            # 拖拽结束后随机改变移动方向
            self.speed_x = random.choice([-1, 1])
            event.accept()
    
    def show_context_menu(self, pos):
        """显示右键菜单"""
        menu = QMenu(self)
        quit_action = QAction("退出宠物", self)
        quit_action.triggered.connect(self.close)
        menu.addAction(quit_action)
        # 菜单透明效果
        menu.setWindowFlags(menu.windowFlags() | Qt.FramelessWindowHint | Qt.NoDropShadowWindowHint)
        menu.setAttribute(Qt.WA_TranslucentBackground)
        menu.exec_(pos)

if __name__ == "__main__":
    app = QApplication(sys.argv)
    pet = DesktopPet()
    pet.show()
    sys.exit(app.exec_())
